export default {
  props: {
    editRecordData: {
      type: Object,
      default: null
    }
  },
  data() {
    return {
      formData: {
        url: '',
        account: '',
        password: '',
        email: ''
      },
      showPassword: false
    };
  },
  computed: {
    isEditing() {
      return this.editRecordData !== null;
    }
  },
  watch: {
    editRecordData: {
      handler(newData) {
        if (newData) {
          this.formData = {
            ...newData
          };
        } else {
          this.resetForm();
        }
      },
      immediate: true
    }
  },
  methods: {
    saveRecord() {
      this.$emit('save-record', {
        ...this.formData
      });
      if (!this.isEditing) {
        this.resetForm();
      }
    },
    resetForm() {
      this.formData = {
        url: '',
        account: '',
        password: '',
        email: ''
      };
    },
    togglePassword() {
      this.showPassword = !this.showPassword;
    }
  }
};
